import {SampleEngine, LiveEngine, EngineError, operationKey, initiateWithRecovery, sleep, recoverable} from './api.mjs';
const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = value => new Intl.NumberFormat('en-TH',{style:'currency',currency:state.event?.currency||'THB',maximumFractionDigits:0}).format(value/100);
let restored;
try { restored=JSON.parse(sessionStorage.getItem('encore.journey.v1')||'null'); } catch { /* Corrupt presentation state is ignored. */ }
const state={view:location.hash==='#engine'?'engine':'customer',mode:'sample',scenario:'normal',events:[],event:null,layout:[],availability:new Map(),selected:[],page:0,hold:null,phase:'select',busy:false,error:'',paymentKey:null,holdKey:null,trace:[],requests:0,errors:0,recoveries:0,completed:0,tickets:[],chart:[],loading:true,metrics:null,restored};
let adapter,passiveRunning=false;
function saveJourney() {
  sessionStorage.setItem('encore.journey.v1',JSON.stringify({mode:state.mode,event:state.event,selected:state.selected,hold:state.hold,holdKey:state.holdKey,paymentKey:state.paymentKey,phase:state.phase}));
}
function trace(text,kind='normal') { state.trace.unshift({text,kind,time:new Date()});state.trace=state.trace.slice(0,40);if(state.view==='engine')render(); }
function request(method,path,status) { state.requests++;if(status===0||status>=500)state.errors++; }
function toast(text) { $('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500); }
function setPhase(phase) { state.phase=phase;saveJourney();render(); }
function sampleAdapter() { return new SampleEngine({onRequest:request,scenario:()=>state.scenario}); }
adapter=sampleAdapter();
function title() { return state.event?.name||state.event?.title||'Live test event'; }
function active() { return !state.hold?Boolean(state.holdKey):state.phase!=='complete'&&(!['expired','failed'].includes(state.phase)||Boolean(state.paymentKey)); }
const STEP_ORDER=['select','reserving','durable','payment','processing','complete'];
function phaseIndex() { return Math.max(0,STEP_ORDER.indexOf(state.phase)); }
function bookingSteps() { const n=phaseIndex();return `<div class="journey-strip">${[['Choose seats','Find your place'],['Reserve','Confirm durable ownership'],['Payment','Recover the same operation'],['Your ticket','Issued after commit']].map(([a,b],i)=>{const current=n===0?0:n<=2?1:n<=4?2:3;return `<div class="journey-step ${i<current?'done':i===current?'current':''}"><span class="step-number">${i<current?'✓':i+1}</span><div><strong>${a}</strong><small>${b}</small></div></div>`}).join('')}</div>`; }
function header() {
  document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-current',b.dataset.view===state.view?'page':'false');});
  $('#breadcrumb-view').textContent=state.view==='customer'?'Customer journey':'Engine dashboard';
  $('#mode-badge').classList.toggle('live',state.mode==='live');$('#mode-badge').innerHTML=`<i></i>${state.mode==='live'?'Live engine':'Sample mode'}`;
  $('#mode-notice').innerHTML=state.mode==='sample'?'PRESENTATION SANDBOX <span>Illustrative seats, payments and activity. No real charge or admission ticket.</span>':'LIVE TEST ENGINE <span>Actual API operations on your configured fixture. Payment uses its development simulator.</span>';
  $('#footer-mode').textContent=state.mode==='sample'?'Sample session · no cloud load test':'Live fixture · customer token held in memory';
}
function hero() { return `<section class="hero" aria-label="Concert details"><div class="hero-copy"><span class="eyebrow">${state.mode==='sample'?'AN EVENING WORTH BEING THERE':'CONNECTED TEST FIXTURE'}</span><h2>${esc(title())}<br><em>${state.mode==='sample'?'Live in Bangkok.':'Your engine. Your journey.'}</em></h2><p>${state.mode==='sample'?'The lights go down. The night opens up.':'Seat geometry below is illustrative; ownership is checked by the engine.'}</p><div class="hero-info"><span>◷ ${esc(state.event?.date||'Active fixture sale')}</span><span>⌖ ${esc(state.event?.venue||'Configured engine')}</span><span>◴ ${esc(state.event?.time||'Server-authoritative expiry')}</span></div></div><div class="hero-art" aria-hidden="true"></div><span class="hero-badge">${state.mode==='sample'?'CONCERT DEMO':'LIVE API'}</span><span class="art-word" aria-hidden="true">FEEL EVERY MOMENT</span></section>`; }
function seats() {
  const slice=state.layout.slice(state.page*96,state.page*96+96), rows=[];
  for(let offset=0;offset<slice.length;offset+=12) {
    const row=slice.slice(offset,offset+12),letter=state.mode==='sample'?row[0]?.seat_id.replace(/\d/g,''):String(state.page*8+offset/12+1);
    rows.push(`<div class="seat-row"><span class="row-label">${esc(letter)}</span>${row.map(s=>{const selected=state.selected.includes(s.seat_id);const status=state.availability.get(s.seat_id)||'UNKNOWN';const unavailable=!selected&&status!=='AVAILABLE';return `<button class="seat ${selected?'selected':status==='HELD'?'held':unavailable?'sold':''}" data-seat="${esc(s.seat_id)}" aria-label="Seat ${esc(s.seat_id)}, ${selected?'selected':esc(status.toLowerCase())}, ${esc(money(s.price))}" aria-pressed="${selected}" ${unavailable||active()||state.busy?'disabled':''}>${selected?'✓':esc(s.seat_id.replace(/^[A-Z]+/,''))}</button>`;}).join('')}<span class="row-label">${esc(letter)}</span></div>`);
  }
  return `<div class="card"><div class="card-head"><div><h3>Find your perfect spot</h3><p>Choose up to 8 seats. Availability can change.</p></div><span class="small-pill">${state.layout.length} seats</span></div><div class="seatmap"><div class="stage">S T A G E</div>${rows.length?rows.join(''):'<div class="empty-state">No seat layout available for this event.</div>'}<div class="seat-legend"><span><i class="legend-box"></i>Available</span><span><i class="legend-box selected"></i>Selected</span><span><i class="legend-box held"></i>Held</span><span><i class="legend-box sold"></i>Sold</span></div>${state.layout.length>96?`<div class="map-pagination"><button class="icon-button" id="previous-page" ${state.page===0?'disabled':''} aria-label="Previous seats">‹</button>Page ${state.page+1} of ${Math.ceil(state.layout.length/96)}<button class="icon-button" id="next-page" ${(state.page+1)*96>=state.layout.length?'disabled':''} aria-label="Next seats">›</button></div>`:''}<p class="map-caption">${state.mode==='sample'?'Illustrative venue · stage geometry is presentation only':'Illustrative layout · live seat IDs and prices from the engine'}</p></div><div class="price-strip">${[...new Set(state.layout.map(s=>s.price))].slice(0,3).map((p,i)=>`<span>${['Front rows','Mid section','Upper section'][i]} <strong>${esc(money(p))}</strong></span>`).join('')}</div></div>`;
}
function expiresIn() { return Math.max(0,Math.ceil((Date.parse(state.hold?.expires_at||'')-Date.now())/1000))||0; }
function countdown() { const sec=expiresIn();return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`; }
function summary() {
  const total=state.layout.filter(s=>state.selected.includes(s.seat_id)).reduce((sum,s)=>sum+Number(s.price),0);
  let status='',button='';
  if(state.phase==='select')button=`<button id="reserve-button" class="button primary full" ${!state.selected.length||state.busy?'disabled':''}>${state.busy?'<span class="spinner"></span>':''}${state.holdKey?'Check original reservation':'Reserve these seats'} <span>→</span></button>`;
  else if(state.phase==='reserving') {status='<div class="status-panel"><strong>Confirming your reservation</strong>Your provisional hold is accepted. Waiting for durable ownership in PostgreSQL.</div>';button=`<button id="check-reservation" class="button primary full" ${state.busy?'disabled':''}>${state.busy?'<span class="spinner"></span>Confirming…':'Check reservation'}</button>`;}
  else if(state.phase==='durable') {status=`<div class="status-panel"><strong>Your seats are reserved</strong><span class="countdown" id="countdown">${countdown()}</span><br>Original hold expiry. Retrying does not extend it.</div>`;button=`<button id="pay-button" class="button primary full" ${state.busy||!expiresIn()?'disabled':''}>Pay with simulator <span>→</span></button><p class="fine-print">Development payment · no card details collected</p><button id="release-button" class="text-button" ${state.busy?'disabled':''}>Release these seats</button>`;}
  else if(['payment','processing'].includes(state.phase)) {status=`<div class="status-panel"><strong>${state.recovering?'Checking the original payment':'Your ticket is on its way'}</strong>Payment and ticket issuance are separate steps. We retrieve the existing operation while it completes.</div>`;button=`<button id="check-order" class="button primary full" ${state.busy?'disabled':''}>${state.busy?'<span class="spinner"></span>Processing…':'Check existing order'}</button>`;}
  else if(state.phase==='expired'||state.phase==='failed') {status='<div class="status-panel warning"><strong>The reservation expired</strong>We cannot extend or reclaim this hold. Any existing payment must still be checked.</div>';if(state.phase==='failed')status='<div class="status-panel warning"><strong>Reservation could not be completed</strong>No payment was initiated. Choose available seats to start a new reservation.</div>';button='<button id="check-order" class="button secondary full">Check existing order</button><button id="new-booking" class="text-button">Choose seats again</button>';}
  return `<aside class="booking-summary"><div class="card"><div class="summary-head"><h3>Your night, your seats</h3><p>${esc(title())}</p></div><div class="summary-body">${status}${state.selected.length?`<div class="seat-chips">${state.selected.map(s=>`<span class="seat-chip">◫ ${esc(s)}</span>`).join('')}</div>`:'<div class="selection-empty"><span>◫</span>Great nights start with a seat.<br>Pick yours on the map.</div>'}<div class="cost-line"><span>Tickets</span><span>${state.selected.length?`${state.selected.length} selected`:'—'}</span></div><div class="cost-line"><span>Service fee</span><span>${state.mode==='sample'?'Included in sample':'Not modeled by engine'}</span></div><div class="cost-line total"><span>Total</span><strong>${esc(money(total))}</strong></div>${state.error?`<p class="inline-error" role="alert">${esc(state.error)}</p>`:''}${button}<p class="fine-print">${state.mode==='sample'?'Sample transaction. No real payment or admission.':'Live fixture operations. Existing authentication and expiry rules apply.'}</p></div></div><div class="integrity-note"><span class="integrity-icon">◇</span><div><strong>One seat. One owner.</strong>Atomic holds, stable payment identities and duplicate-safe ticket issuance.</div></div></aside>`;
}
function ticket() { return `<section class="ticket-view"><div class="ticket-intro"><div class="success-check">✓</div><span class="eyebrow">${state.mode==='sample'?'SAMPLE BOOKING COMPLETE':'ENGINE CONFIRMED FULFILLED'}</span><h2>You’re going. Make it a night.</h2><p>${state.tickets.length} ticket${state.tickets.length===1?'':'s'} issued. Payment and booking identities are preserved.</p></div>${state.tickets.map((t,i)=>`<article class="ticket" style="margin-bottom:14px"><div class="ticket-main"><span class="eyebrow">${state.mode==='sample'?'DEMO TICKET':'LIVE FIXTURE TICKET'}</span><h3>${esc(title())}</h3><div class="ticket-tags"><span>⌖ ${esc(state.event?.venue||'Test fixture')}</span><span>◷ ${esc(state.event?.date||'Engine test')}</span></div><div class="ticket-code">Ticket ${esc(t.id||t.ticket_id||t)}<br>Order ${esc(state.hold?.order_id)}</div></div><div class="ticket-stub"><span class="eyebrow">SEAT</span><strong>${esc(t.seat_id||state.selected[i]||'Assigned')}</strong><div class="barcode" aria-hidden="true"></div><small>Visual demo barcode<br>Not an admission credential</small></div></article>`).join('')}<div class="ticket-actions"><button id="new-booking" class="button primary">Book more seats <span>→</span></button><button data-view="engine" class="button secondary">See the engine behind it <span>↗</span></button></div><p class="ticket-bottom">${state.mode==='sample'?'Illustrative tickets from this browser’s sample session.':'Retrieved from the existing authorized engine order. No production credential is generated.'}</p></section>`; }
function customer() { return `<div class="page-heading"><div><h1>A seat for your next great night.</h1><p>Explore the journey from choosing a seat to holding your ticket.</p></div><div class="heading-action"><select id="event-picker" class="event-picker" aria-label="Select concert" ${state.hold||state.holdKey||state.busy?'disabled':''}>${state.events.map(e=>`<option value="${esc(e.id)}" ${e.id===state.event?.id?'selected':''}>${esc(e.name||e.title||e.id.slice(0,12))}</option>`).join('')}</select></div></div>${state.phase==='complete'?ticket():hero()+`<div class="booking-grid">${seats()}${summary()}</div>`+bookingSteps()}`; }
function chart() {
  const values=state.chart.length?[0,...state.chart]:[0,0],max=Math.max(4,...values),width=540,height=120;
  const points=values.map((v,i)=>`${i/(Math.max(values.length-1,1))*width},${height-v/max*height}`).join(' ');
  return `<svg class="chart-svg" viewBox="0 0 540 150" role="img" aria-label="Cumulative API calls observed in this browser session"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#9dc561" stop-opacity=".25"/><stop offset="100%" stop-color="#9dc561" stop-opacity=".015"/></linearGradient></defs>${[0,40,80,120].map(y=>`<line x1="0" y1="${y}" x2="540" y2="${y}" stroke="#eaf0e2" stroke-dasharray="3 5"/>`).join('')}<polygon points="0,120 ${points} 540,120" fill="url(#chart-fill)"/><polyline points="${points}" fill="none" stroke="#8fb252" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/></svg>`;
}
function dashboard() {
  const complete=state.phase==='complete';const n=phaseIndex();
  const stages=[['◫','Seat intake','Redis'],['▤','Durable hold','PostgreSQL'],['↔','Payment','Callback'],['⌁','Ticket issuance','Kafka + consumer'],['✓','Confirmed','Customer']];
  const current=n===0?-1:n===1?0:n===2?1:n===3?2:n===4?3:4;
  const metrics=state.metrics;
  return `<div class="page-heading"><div><h1>The engine behind every ticket.</h1><p>${state.mode==='sample'?'Watch the same sample journey move through its stages.':'Browser-observed journeys and one upstream API process snapshot.'}</p></div><button data-view="customer" class="button secondary">Open customer view <span>↗</span></button></div><div class="stat-grid">${[['Issued tickets',state.completed,'Confirmed in this browser session'],['API calls',state.requests,'Observed by this browser'],['Recovery checks',state.recoveries,'Existing operation inquiry'],['Current journey',complete?'Complete':['expired','failed'].includes(state.phase)?'Needs attention':active()?'In progress':'Ready','No aggregate throughput claim']].map(([a,b,c])=>`<div class="card stat-card"><div class="stat-label">${a}<span>↗</span></div><div class="stat-value" style="${typeof b==='string'?'font-size:22px;margin-top:14px':''}">${esc(b)}</div><div class="stat-caption ${a==='Issued tickets'?'good':''}">${c}</div></div>`).join('')}</div><div class="dashboard-grid"><div><section class="card"><div class="card-head"><div><h3>Session activity</h3><p>Cumulative API calls · browser session only</p></div><span class="small-pill">${state.mode==='sample'?'SAMPLE':'LIVE CLIENT'}</span></div><div class="activity-chart"><div class="chart-caption"><i></i> Customer and status calls <span style="margin-left:auto">${state.requests} observed</span></div>${chart()}<div class="chart-axis"><span>Recent visible-session samples</span><span>5 second refresh</span><span>Now</span></div></div></section><section class="card flow-card"><div class="card-head"><div><h3>From a seat to a ticket</h3><p>Customer-observed milestones</p></div><span class="small-pill">${state.mode==='sample'?'SIMULATED FLOW':'API-OBSERVED'}</span></div><div class="flow-nodes">${stages.map(([icon,a,b],i)=>`<div class="flow-node ${i<current||complete?'done':i===current?'current':''}"><div class="node-icon">${i<current||complete?'✓':icon}</div><strong>${a}</strong><span>${b}</span></div>`).join('')}</div><p class="flow-note">${state.mode==='sample'?'Presentation model. Stages illustrate the engine contract; no backend services are contacted.':'Milestones reflect API responses. Internal queue transitions are not independently observed here.'}</p></section><div class="reference-banner"><div><strong>138.49 paid-and-issued tickets/s</strong><br>Verified reference · five-minute test · not this session or an hourly qualification.</div><a href="https://github.com/chawansit/flash-ticketing/blob/codex/customer-recovery-2026-10-10/docs/capacity/cce/fixed-budget-140-throughput-result-2026-10-15.json" target="_blank" rel="noreferrer">View evidence ↗</a></div></div><div><section class="card"><div class="card-head"><div><h3>Journey activity</h3><p>One trace shared with the customer view</p></div><span class="small-pill">${state.trace.length} events</span></div><div class="activity-list">${state.trace.length?state.trace.slice(0,9).map(row=>`<div class="activity-item"><span class="activity-dot" ${row.kind==='recovery'?'style="background:#d4a365"':''}></span><div><strong>${esc(row.text)}</strong><small>${row.time.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit'})} · ${state.mode==='sample'?'sample session':'client observation'}</small></div></div>`).join(''):'<div class="activity-empty">Your next booking starts the story.<br>Choose seats in the customer view.</div>'}</div>${state.mode==='sample'?`<div class="sample-controls"><label for="scenario">PRESENTATION SCENARIO</label><select id="scenario" class="scenario-select" ${active()||state.busy?'disabled':''}><option value="normal" ${state.scenario==='normal'?'selected':''}>Standard booking</option><option value="recover" ${state.scenario==='recover'?'selected':''}>Lost payment response → recover</option><option value="conflict" ${state.scenario==='conflict'?'selected':''}>Seat taken before reservation</option></select><p>Scenarios affect sample data only. Lost-response recovery looks up the same payment.</p><button id="reset-sample" class="text-button">Reset sample session</button></div>`:''}</section><section class="card visibility-card"><h3>What this view can see</h3><p>${state.mode==='sample'?'Only this browser’s simulated journey.':'One API endpoint and this browser. Counters may come from different replicas; no aggregate rate is derived.'}</p><div class="health-row"><span>Customer journey</span><strong>${active()?'IN PROGRESS':complete?'CONFIRMED':'READY'}</strong></div><div class="health-row"><span>Kafka consumer lag</span><strong>NOT CONNECTED</strong></div><div class="health-row"><span>RDS CPU and lock waits</span><strong>NOT CONNECTED</strong></div><div class="health-row"><span>Global queue drain</span><strong>NOT MEASURED</strong></div>${state.mode==='live'?`<div class="operator-metrics"><div class="health-row"><span>API process HTTP requests</span><strong>${metrics?.httpRequests??'Unavailable'}</strong></div><div class="health-row"><span>API process 5xx responses</span><strong>${metrics?.httpErrors??'Unavailable'}</strong></div><div class="health-row"><span>DB unavailable responses</span><strong>${metrics?.dbUnavailable??'Unavailable'}</strong></div></div>`:''}</section></div></div>`;
}
function render() { header();$('#view').innerHTML=state.loading?'<div class="loading-state"><span class="spinner"></span>Preparing your experience…</div>':state.view==='engine'?dashboard():state.event?customer():`<div class="empty-state"><h2>Waiting for an event</h2><p>${esc(state.error||'Connect an engine with an isolated open fixture.')}</p><button id="retry-events" class="button secondary">Try again</button></div>`;bind(); }
function view(name) { state.view=name;history.replaceState(null,'','#'+name);render(); }
function bind() {
  document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));
  document.querySelectorAll('[data-seat]').forEach(b=>b.onclick=()=>{if(active()||state.busy)return;const seat=b.dataset.seat;if(state.holdKey){toast('Check or resolve the original reservation before changing its seats.');return;}if(state.selected.includes(seat))state.selected=state.selected.filter(s=>s!==seat);else if(state.selected.length<8)state.selected.push(seat);else return toast('Choose up to 8 seats per reservation.');state.selected.sort();state.error='';saveJourney();render();});
  const handlers={'reserve-button':reserve,'check-reservation':checkReservation,'pay-button':pay,'check-order':checkOrder,'release-button':release,'new-booking':newBooking,'reset-sample':resetSample,'retry-events':()=>loadEvents()};
  for(const [id,handler] of Object.entries(handlers))if($('#'+id))$('#'+id).onclick=()=>handler();
  if($('#event-picker'))$('#event-picker').onchange=e=>loadEvent(state.events.find(x=>x.id===e.target.value)).catch(error=>{state.error=explain(error);state.event=null;render();toast(state.error);});
  if($('#previous-page'))$('#previous-page').onclick=()=>{state.page--;render();};if($('#next-page'))$('#next-page').onclick=()=>{state.page++;render();};
  if($('#scenario'))$('#scenario').onchange=e=>{state.scenario=e.target.value;trace('Scenario selected: '+e.target.selectedOptions[0].textContent);toast('Scenario ready. Start a booking in the customer view.');};
}
async function loadEvents(forced) {
  state.loading=true;state.event=null;state.events=[];state.layout=[];state.availability=new Map();render();
  try { let events=await adapter.events();if(!Array.isArray(events))events=events.events||[];
    if(forced)events=[{id:forced,name:'Live test event',currency:'THB'},...events.filter(e=>e.id!==forced)];
    if(state.mode==='live'&&!forced){const now=Date.now();events=events.filter(e=>!e.sale_ends||Date.parse(e.sale_ends)>now);}
    state.events=events;const prior=state.restored?.mode===state.mode?state.restored:null;
    const event=events.find(e=>e.id===prior?.event?.id)||events[0]||prior?.event;
    if(!event){state.event=null;throw new EngineError('No open fixture in the first 100 events. Enter a fixture event ID in Connect engine.');}
    await loadEvent(event,false);
    if((prior?.hold||prior?.holdKey)&&prior.event?.id===event.id) {Object.assign(state,{selected:prior.selected||[],hold:prior.hold,holdKey:prior.holdKey,paymentKey:prior.paymentKey,phase:prior.phase==='complete'?'processing':prior.phase});trace('Restored original order identity · authentication remains required');state.restored=null;if(['payment','processing'].includes(state.phase))await checkOrder();}
  } catch(error) {state.error=error.code||'Unable to load events';toast(state.error);}
  finally{state.loading=false;render();}
}
async function loadEvent(event,redraw=true) { if(!event)return;state.event=event;state.layout=[];state.availability=new Map();state.page=0;state.selected=[];state.holdKey=null;state.error='';state.layout=(await adapter.layout(event.id)).seats||[];state.availability=new Map((await adapter.availability(event.id)).seats.map(s=>[s.seat_id,s.status]));if(redraw){saveJourney();render();} }
async function refreshAvailability(){if(!state.event)return;state.availability=new Map((await adapter.availability(state.event.id)).seats.map(s=>[s.seat_id,s.status]));}
async function reserve() {
  if(state.busy||!state.selected.length)return;state.busy=true;state.error='';state.holdKey ||= operationKey();saveJourney();render();
  try {state.hold=await adapter.reserve(state.event.id,[...state.selected],state.holdKey);trace('Hold accepted · original expiry recorded');setPhase(state.hold.persistence_status==='PENDING'?'reserving':'durable');if(state.phase==='reserving')await waitDurable();else trace('Reservation is durable');}
  catch(e){state.error=explain(e);if(e.status===409&&!state.hold){state.holdKey=null;await refreshAvailability();trace('Seat conflict · no booking was completed');}toast(state.error);}
  finally{state.busy=false;saveJourney();render();}
}
async function waitDurable() { const deadline=Math.min(Date.parse(state.hold.expires_at),Date.now()+30000);while(Date.now()<deadline){if(document.hidden){await sleep(1000);continue;}const result=await adapter.command(state.event.id,state.hold.command_id);if(result.persistence_status==='DURABLE'){state.hold={...state.hold,...result};setPhase('durable');trace('Durable hold confirmed · checkout unlocked');return;}if(result.persistence_status==='FAILED'){setPhase('failed');trace('Reservation failed · no payment initiated');throw new EngineError(result.failure_code||'RESERVATION_FAILED',409);}await sleep(700+Math.random()*250);}throw new EngineError('Reservation is still processing. Check the same command again.'); }
async function checkReservation(){if(state.busy)return;state.busy=true;state.error='';render();try{await waitDurable();}catch(e){state.error=explain(e);}finally{state.busy=false;render();}}
function explain(e){const names={SEAT_UNAVAILABLE:'That seat was taken before your hold completed. Choose another available seat.',HOLD_EXPIRED:'The original hold expired. Its expiry cannot be extended by retrying.',SIMULATOR_DISABLED:'This engine disables simulated payment. A real gateway adapter is required.',PAYMENT_INQUIRY_UNAVAILABLE:'Payment may have succeeded. Inquiry is unavailable; keep this order and check again.',PAYMENT_OUTCOME_UNKNOWN:'Payment is unresolved. Keep this order and check its existing status.',NETWORK_RESPONSE_UNKNOWN:'The response was lost. Check the original operation with the same identity.'};return names[e.code]||String(e.code||'The engine could not confirm this operation.');}
async function pay() {
  if(state.busy||state.phase!=='durable')return;if(!expiresIn()){setPhase('expired');return;}
  state.busy=true;state.error='';state.paymentKey ||= operationKey();setPhase('payment');trace('Payment initiation · stable operation key');
  try {await initiateWithRecovery(adapter,state.hold.order_id,state.paymentKey,{outcome:'SUCCEEDED',delay_seconds:1,duplicates:3},{deadline:Date.parse(state.hold.expires_at),onRecovery:text=>{if(text.startsWith('Checking'))state.recoveries++;state.recovering=true;trace(text,'recovery');toast(text);render();}});state.recovering=false;trace('Payment operation recorded · awaiting ticket issuance');setPhase('processing');await waitOrder(30000);}
  catch(e){state.error=explain(e);if(e.status===409&&e.code.includes('EXPIRED'))setPhase('expired');else setPhase('processing');trace('Confirmation pending · existing order retained','recovery');toast(state.error);}
  finally{state.busy=false;saveJourney();render();}
}
async function waitOrder(ms) {const deadline=Date.now()+ms;while(Date.now()<deadline){if(document.hidden){await sleep(1000);continue;}let order;try{order=await adapter.order(state.hold.order_id);}catch(e){if(!recoverable(e))throw e;await sleep(1000);continue;}if(order.status==='FULFILLED'&&order.tickets?.length){state.tickets=order.tickets;state.completed+=order.tickets.length;setPhase('complete');trace('Tickets issued · existing identities confirmed');await refreshAvailability();return;}if(['EXPIRED','FAILED','REFUND_PENDING','REFUNDED'].includes(order.status)){setPhase(order.status==='EXPIRED'?'expired':'processing');throw new EngineError('Order '+order.status.toLowerCase()+'. Check its existing payment or review obligation.');}await sleep((adapter.pollMs||900)*(0.8+Math.random()*.4));}throw new EngineError('Still processing. Your order is retained; check it again shortly.');}
async function checkOrder(){if(state.busy||!state.hold)return;state.busy=true;state.error='';render();try{await waitOrder(5000);}catch(e){state.error=explain(e);}finally{state.busy=false;render();}}
async function release(){if(state.busy||!state.hold)return;state.busy=true;try{await adapter.release(state.hold.hold_id);trace('Hold released with original ownership');clearBooking();await refreshAvailability();}catch(e){state.error=explain(e);}finally{state.busy=false;render();}}
function clearBooking(){state.hold=null;state.holdKey=null;state.paymentKey=null;state.selected=[];state.tickets=[];state.error='';state.phase='select';saveJourney();}
async function newBooking(){if(state.busy)return;if(state.hold&&state.paymentKey&&state.phase!=='complete'){toast('Resolve the existing payment before starting another booking.');return;}clearBooking();await refreshAvailability();render();}
function resetSample(){if(state.busy||state.mode!=='sample')return;adapter.reset();clearBooking();state.completed=state.recoveries=state.errors=state.requests=0;state.chart=[];state.trace=[];trace('Sample session reset · no engine data changed');loadEvents();}

$('#connect-button').onclick=async()=>{state.bridge=false;$('#connect-error').textContent='';$('#connect-dialog').showModal();try{const result=await fetch('/demo-config',{cache:'no-store'});const cfg=await result.json();state.bridge=cfg.engineConfigured===true;$('#bridge-status').textContent=state.bridge?'Local bridge ready. Use a short-lived customer token and an isolated fixture.':'Local bridge is running. Set DEMO_ENGINE_URL and restart it to enable live mode.';}catch{$('#bridge-status').textContent='This hosted preview uses sample data. Start web/demo/serve.py locally with DEMO_ENGINE_URL to connect the engine.';}$('#live-button').disabled=!state.bridge;};
$('#close-connect').onclick=()=>$('#connect-dialog').close();
$('#sample-button').onclick=()=>{if(state.busy||active()){toast('Finish or release the current booking before switching modes.');return;}state.mode='sample';adapter=sampleAdapter();clearBooking();state.restored=null;$('#connect-dialog').close();loadEvents();};
$('#connect-form').onsubmit=async e=>{e.preventDefault();if(!state.bridge)return;if(state.busy||active()){return $('#connect-error').textContent='Finish or release the current booking before switching modes.';}const token=$('#engine-token').value.trim(),event=$('#engine-event').value.trim();if(!token)return $('#connect-error').textContent='Enter a short-lived customer token.';if(event&&!/^[0-9a-f-]{36}$/i.test(event))return $('#connect-error').textContent='Enter an engine event UUID.';state.mode='live';adapter=new LiveEngine({token,onRequest:request});$('#engine-token').value='';clearBooking();state.restored=restored?.mode==='live'?restored:null;state.trace=[];trace('Live connection selected · no fallback to sample data');$('#connect-dialog').close();await loadEvents(event);};
setInterval(()=>{if($('#countdown'))$('#countdown').textContent=countdown();if(state.phase==='durable'&&!expiresIn()&&!state.busy){setPhase('expired');trace('Original hold expired · new initiation blocked');}},1000);
setInterval(async()=>{if(document.hidden||passiveRunning||state.loading)return;passiveRunning=true;try{if(state.event&&!state.busy&&state.phase==='select'){await refreshAvailability();if(state.view==='customer')render();}if(state.view==='engine'&&state.mode==='live'){try{state.metrics=await adapter.metrics();}catch{state.metrics=null;}}state.chart.push(state.requests);state.chart=state.chart.slice(-13);if(state.view==='engine')render();}catch{/* Passive failure does not initiate recovery or switch adapters. */}finally{passiveRunning=false;}},5000);
window.addEventListener('hashchange',()=>{state.view=location.hash==='#engine'?'engine':'customer';render();});
if(restored?.mode==='live'){state.restored=null;toast('Previous live order retained. Reconnect with the same customer to retrieve it.');}
trace('Sample environment ready · no backend requests');
loadEvents();
